class Random {
 public:
  unsigned int nextInt() {
    unsigned int ret = 0u;

    const unsigned int t = seed_[0] ^ (seed_[0] << 11);
    seed_[0] = seed_[1];
    seed_[1] = seed_[2];
    seed_[2] = seed_[3];
    return seed_[3] = (seed_[3] ^ (seed_[3] >> 19)) ^ (t ^ (t >> 8));
  }

  unsigned int nextInt(int n) { return nextInt() % n; }

  float nextReal() { return (float)nextInt() / (float)UINT_MAX; }

  Random(unsigned int initial_seed) {
    unsigned int s = initial_seed;
    for (int i = 1; i <= 4; i++) {
      seed_[i - 1] = s = 1812433253U * (s ^ (s >> 30)) + i;
    }
  }

 private:
  unsigned int seed_[4];
};

