int solve2e(float root[], float A, float B, float C) {
  if (fabsf(A) <= 1.0e-6f) {
    float x = -C / B;
    root[0] = x;
    return 1;
  } else {
    float D = B * B - A * C;
    if (D < 0) {
      return 0;
    } else if (D == 0) {
      float x = -B / A;
      root[0] = x;
      return 1;
    } else {
      float x1 = (fabsf(B) + sqrtf(D)) / A;
      if (B >= 0.0) {
        x1 = -x1;
      }
      float x2 = C / (A * x1);
      if (x1 > x2) {
        float tmp = x1;
        x1 = x2;
        x2 = tmp;
      }

      root[0] = x1;
      root[1] = x2;
      return 2;
    }
  }
}

