  void Set(int axis, float pos) const {
    axis_ = axis;
    pos_ = pos;
  }

  bool operator()(unsigned int i) const {
    int axis = axis_;
    float pos = pos_;

    nanort::real3<float> p0(&vertices_[3 * (2 * i + 0)]);
    nanort::real3<float> p1(&vertices_[3 * (2 * i + 1)]);

    float center = (p0[axis] + p1[axis]) / 2.0f;

    return (center < pos);
  }

 private:
  mutable int axis_;
  mutable float pos_;
  const float *vertices_;
};

